/** Looks up by slug. The root (`/docs/runtime`) is the empty string; an unknown slug is `null`. */
export function findRuntimeDocEntry(slug: string): RuntimeDocEntry | null {
	return RUNTIME_DOC_ENTRIES.find((doc) => doc.slug === slug) ?? null;
}
